from envparse import parse_env

assert parse_env('A=1\nB = 2 \n') == {'A': '1', 'B': '2'}
assert parse_env('# c\n\n   \nA=1') == {'A': '1'}
assert parse_env('A=\"x\\ny\"') == {'A': 'x\ny'}
assert parse_env(\"A='x\\\\ny'\") == {'A': 'x\\ny'}
assert parse_env('A=hello  # trailing') == {'A': 'hello'}
assert parse_env('A=a#b') == {'A': 'a#b'}
